from pathlib import Path
import json
items=[]
def f(name,label,value,min=0,max=100,step='any'):return dict(name=name,label=label,value=value,min=min,max=max,step=step)
def text(name,label,value,help):return dict(name=name,label=label,value=value,type='textarea',help=help)
def sel(name,label,options):return dict(name=name,label=label,type='select',options=options)
scale=sel('scale','Maximum GPA scale',[['4','4.0'],['4.33','4.33'],['4.5','4.5'],['5','5.0'],['9','9.0'],['10','10.0']])
grades=lambda value:text('grades','Percentage grades',value,'Separate percentage grades with commas, spaces or new lines; up to 1,000 values, each from 0 to 100.')
def add(key,slug,title,category,desc,fields,formula,example,detail,faq):
 items.append(dict(key=key,slug=slug,title=title,category=category,description=desc,fields=fields,intro=desc,formula=formula,example=example,detail=detail,note=detail,steps=['Enter the values from your syllabus, marks or personal study plan.','Check the units and assumptions shown below the inputs.','Select Calculate, then compare the result with the worked example and your actual course rules.'],faq=faq))
add('remaining','remaining-grade-calculator','Remaining Grade Calculator','grades','Find the average needed across all ungraded work from your earned course contribution.',[f('earned_contribution','Course percentage points already earned',45),f('completed_weight','Completed course weight (%)',60),f('target','Target course grade (%)',80)],'Required remaining average = (Target − Earned course contribution) ÷ (1 − Completed weight / 100)','Completed work covers 60% of the course and has contributed 45 percentage points. To finish at 80%, the remaining 40% must supply 35 points: 35 ÷ 0.40 = 87.50%.','Enter the contribution to the full course, not your normalized current average. For example, 75% on completed work worth 60% contributes 45 points. The completed contribution cannot exceed the completed weight. All remaining work is modeled as one combined average; category-specific pass rules are not applied.',[('What is an earned course contribution?','Multiply each completed score by its course weight, then add the results. A score of 80% worth 25% contributes 20 percentage points.'),('Can the remaining work contain several assessments?','Yes. The answer is the combined weighted average required across that work, not a required score for every individual assessment.')])
add('points-target','points-needed-calculator','Points Needed Calculator','grades','Work out how many remaining marks you need in a points-based course.',[f('earned','Points earned so far',120,0,1e7),f('completed_possible','Points possible so far',160,0,1e7),f('remaining_points','Points still available',40,.000001,1e7),f('target','Target final percentage',75)],'Required points = Target / 100 × (Completed possible + Remaining possible) − Earned points','You have earned 120 of 160 points, with 40 points left. A 75% target means 150 points out of 200 overall, so 30 more points are required. This is 75% of the remaining 40.','Use only for a course that pools points. An instructor who weights categories separately may produce a different result. Decimal marks are supported. The displayed minimum rounds upward to two decimals; if marks are awarded in whole points, round upward again to a whole point.',[('Can I use category-weighted grades?','No. Use this tool only when the final percentage equals total earned points divided by total possible points.'),('What does Not reachable mean?','The required points exceed all remaining marks available. Check your inputs, course rules or target.')])
add('assignment-target','assignment-average-target-calculator','Assignment Average Target Calculator','grades','Find the average required on future assignments when every assignment counts equally.',[f('current_average','Current assignment average (%)',70),f('completed_count','Completed assignments',3,1,1e6,'1'),f('remaining_count','Remaining assignments',2,1,1e6,'1'),f('target','Target final average (%)',80)],'Future average = [Target × (Completed count + Remaining count) − Current average × Completed count] ÷ Remaining count','Three assignments average 70%. With two left, an 80% final average requires 80 × 5 − 70 × 3 = 190 percentage-score units across the last two: 190 ÷ 2 = 95%.','All assignments must carry equal weight, regardless of their raw point totals. Include awarded zeroes in the current average. This model does not drop scores or add extra credit. If assignment weights differ, use the remaining-grade or weighted-grade calculator.',[('Do assignments need the same point total?','They need the same final weighting. Equal point totals alone are not enough if your instructor assigns different weights.'),('Does 95% mean both future assignments must score 95%?','No. Their combined equally weighted average must be at least 95%; individual scores can differ.')])
add('improvement','grade-improvement-calculator','Grade Improvement Calculator','grades','Estimate your revised course grade when one assessment mark is replaced.',[f('current_grade','Current course grade (%)',75),f('old_score','Existing assessment score (%)',60),f('new_score','Replacement score (%)',90),f('weight','Assessment course weight (%)',20,.000001)],'New course grade = Current grade + (Replacement score − Existing score) × Weight / 100','A course grade of 75% includes an assessment worth 20%, originally scored at 60%. Replacing that mark with 90% adds (90 − 60) × 0.20 = 6 points, giving 81%.','Your current course grade must already include the old assessment at the stated full-course weight. The tool replaces that mark; it does not add another assessment. It rejects combinations where the implied contribution from other work is outside 0–100%. Permission to replace a mark depends on your instructor.',[('Will a 10-point assessment improvement raise my course grade by 10?','Only if the assessment is the whole course. At 20% weight, a 10-point improvement raises the course grade by 2 percentage points.'),('Does this apply an actual regrade?','No. It models a possible replacement. Your instructor decides whether a revised mark is awarded.')])
add('drop-lowest','drop-lowest-grade-calculator','Drop Lowest Grade Calculator','grades','See your equal-weight average after dropping a chosen number of lowest scores.',[grades('60, 80, 90, 100'),f('drop_count','Number of lowest scores to drop',1,0,999,'1')],'Adjusted average = Sum of retained grades ÷ Number of retained grades','For grades 60%, 80%, 90% and 100%, dropping the lowest one leaves 80%, 90% and 100%. The revised average is 270 ÷ 3 = 90%, compared with 82.5% before the drop.','Use within one category where all scores are equally weighted. At least one score must remain. Equal lowest scores can be removed in any order because the retained average is identical. A point-based category or a rule protecting certain assessments needs a different calculation.',[('Can I drop every score?','No. An average needs at least one retained score.'),('What if assignments have different possible points?','This tool averages percentages equally. It does not select which point-based assignment would maximize your grade.')])
add('must-pass','must-pass-final-calculator','Must-Pass Final Calculator','grades','Combine your course passing target with a separate minimum final-exam requirement.',[f('current_grade','Current grade excluding final (%)',80),f('course_pass','Required course grade (%)',50),f('final_weight','Final exam weight (%)',40,.01),f('exam_pass','Minimum permitted final score (%)',40)],'Minimum final score = max[(Course pass − Current × (1 − Weight / 100)) ÷ (Weight / 100), Exam minimum]','With an 80% current grade, a 50% course threshold and a 40%-weight final, the weighted-average target alone needs 5% on the exam. If the exam must separately be passed at 40%, the actual minimum is 40%.','Use the actual thresholds in your syllabus. The current grade excludes the final. This calculator combines two mathematical conditions only; it does not model attendance, minimum component scores or compulsory submissions. A result over 100% is unattainable on a standard capped exam.',[('Why is this different from the ordinary final calculator?','Some courses require a minimum final-exam score even when the overall weighted course average is already high enough.'),('Can a course still be failed after meeting this result?','Yes, if there are other requirements. Check the complete syllabus rather than relying on these two thresholds alone.')])
add('two-part','two-part-final-calculator','Two-Part Final Calculator','grades','Calculate the score needed on the unfinished part of a final exam.',[f('current_grade','Course grade excluding entire final (%)',80),f('target','Target course grade (%)',85),f('final_weight','Entire final weight in course (%)',40,.01),f('part_one_weight','Part 1 share of final (%)',50,0,99.999999),f('part_one_score','Part 1 score (%)',90)],'Part 2 score = (Required entire-final score − Part 1 score × Part 1 share) ÷ (1 − Part 1 share)','An 80% current grade and 85% course target, with the final worth 40%, require a 92.5% final average. If Part 1 is half of the final and scores 90%, Part 2 must score (92.5 − 45) ÷ 0.50 = 95%.','The two parts must cover the entire final. Enter Part 1 weight as its share of the final, not of the course. Your current course grade must exclude both parts, including Part 1. If Part 1 covers 100% there is no unfinished part to solve for, so that input is rejected.',[('Is the Part 1 weight a course weight?','No. A 50% share of a final worth 40% of the course represents 20% of the full course.'),('What if the final has three unfinished sections?','You can treat all unfinished sections as one combined Part 2 average if their relative weights are known.')])
add('test-category','final-counts-as-test-calculator','Final Counts as a Test Calculator','grades','Plan a final that changes your existing test-category average rather than adding a separate category.',[f('current_grade','Current overall course grade (%)',80),f('target','Target course grade (%)',82),f('test_weight','Test category weight (%)',50,.000001),f('test_average','Current test-category average (%)',70),f('test_count','Existing equally weighted tests',3,1,1e6,'1'),f('final_equivalent','Final counts as this many tests',1,.000001,100)],'Final score = {[(Target − Current + w × Test average) ÷ w] × (n + k) − n × Test average} ÷ k','The current course grade is 80%, tests count 50%, and three existing tests average 70%. A final counting as one test must score 86% to reach 82% overall: the test average becomes (210 + 86) ÷ 4 = 74%, raising the course by 2 points.','All existing tests must have equal weight. The final can count as several equivalent tests, while other category contributions stay fixed. The current grade must already include the test category at its full syllabus weight. Dropped tests, a separate final category or ungraded non-test work are not included.',[('What does equivalent tests mean?','If the final counts twice as much as one ordinary test, enter 2. This describes relative weighting inside the test category.'),('Can this handle dropping the lowest test?','No. A drop changes which scores enter the category average and must be modeled separately.')])
add('negative-marking','negative-marking-calculator','Negative Marking Calculator','scores','Calculate raw exam marks with a configurable penalty for incorrect answers.',[f('total_questions','Total questions',20,1,1e6,'1'),f('correct','Correct answers',12,0,1e6,'1'),f('incorrect','Incorrect answers',5,0,1e6,'1'),f('marks_per_correct','Marks for a correct answer',4,.000001,1000),f('penalty','Marks deducted per incorrect answer',1,0,1000)],'Raw marks = Correct × Marks per correct − Incorrect × Penalty','In a 20-question exam, 12 correct answers at 4 marks each earn 48 marks. Five wrong answers lose 5 marks at a penalty of 1 each. The result is 43/80 = 53.75%, with three unanswered questions.','Question counts must be whole numbers and correct plus incorrect cannot exceed the total. Unanswered questions earn zero and have no penalty. Negative totals are displayed without a zero floor. This is a configurable raw-score calculation, not an official prediction for a named examination.',[('Can the result be negative?','Yes. If penalties exceed marks earned, the raw score is negative. An exam provider may apply a zero floor or another policy afterward.'),('Does this account for section-specific penalties?','No. Use separate calculations for sections with different rules, then combine the awarded marks correctly.')])
add('minimum-correct','minimum-correct-answers-calculator','Minimum Correct Answers Calculator','scores','Convert a target test percentage into the minimum whole number of correct answers.',[f('total_questions','Total equal-value questions',33,1,1e6,'1'),f('target','Target percentage',80)],'Minimum correct = ceiling(Total questions × Target / 100)','For 33 questions and an 80% target, 33 × 0.80 = 26.4. Round up to 27 correct answers. That allows at most six incorrect or blank answers and produces 81.82%.','Assumes equal-value questions, no partial credit and no negative marking. The minimum is rounded upward to a whole answer. A target of 0% requires zero correct and 100% requires every answer correct. Raw question counts cannot predict a scaled score.',[('Why does the resulting percentage exceed my target?','Whole correct-answer counts cause score steps. When the target falls between steps, the next higher count is required.'),('Can I use this for questions worth different marks?','No. Use awarded points and the points-needed calculator instead.')])
add('rubric','rubric-grade-calculator','Rubric Grade Calculator','scores','Combine rubric criteria that use different mark totals and percentage weights.',[text('rows','Rubric rows: earned, possible, weight (%)','8, 10, 40\n18, 20, 60','One criterion per line. Enter earned marks, possible marks and percentage weight, separated by commas. Weights must total 100%.')],'Rubric percentage = Σ[(Earned ÷ Possible × 100) × Weight / 100]','A criterion scored 8/10 at 40% weight contributes 32 percentage points. Another scored 18/20 at 60% contributes 54 points. The completed rubric grade is 86%.','Include every criterion and use positive possible marks and weights. Earned marks cannot exceed possible marks. Weights must total 100%; incomplete rubrics are rejected so they are not mistaken for a final assessment result. A categorical rubric must first be converted into marks using the actual rubric rules.',[('Why not average earned marks directly?','Different criteria can have different maximum marks and importance. Each must first be converted to a percentage.'),('Can I enter an ungraded criterion as zero?','Only enter zero if it has actually been awarded. This calculator expects a completed rubric.')])
add('statistics','grade-statistics-calculator','Grade Statistics Calculator','scores','Summarize a group of percentage grades with median, mean, spread and population standard deviation.',[grades('60, 70, 80, 90, 100')],'Median = middle sorted score; population SD = √[Σ(score − mean)² ÷ n]','The grades 60, 70, 80, 90 and 100 have a median and mean of 80%. Their range is 40 percentage points and their population standard deviation is approximately 14.14 points.','This summary treats all entered scores as the full population and weights them equally. It does not calculate sample standard deviation, decide a curve or assign passing grades. Population standard deviation uses n in the denominator; a sample estimate typically uses n − 1. Up to 1,000 scores are accepted.',[('What happens with an even number of grades?','The median is the mean of the two middle sorted values.'),('Does standard deviation show whether my class did well?','It measures spread, not academic quality or fairness. Interpret it with assessment context and the actual grading policy.')])
add('percentile','class-percentile-rank-calculator','Class Percentile Rank Calculator','scores','Estimate your relative position in a class using a tie-aware midrank percentile.',[f('below','Students scoring below your score',18,0,1e6,'1'),f('equal','Students tied, including you',3,1,1e6,'1'),f('above','Students scoring above your score',9,0,1e6,'1')],'Midrank percentile = (Below + 0.5 × Equal) ÷ (Below + Equal + Above) × 100','If 18 students score below you, three including you share your score, and nine score above, the class size is 30. Your midrank percentile is (18 + 1.5) ÷ 30 × 100 = 65.','Counts refer to the same assessment and class group. Include yourself among tied students. This tool uses the midrank convention, not an official standardized-test percentile. Other conventions handle ties differently. A percentile rank is distinct from the percentage of exam marks earned.',[('Is the 65th percentile the same as a 65% grade?','No. A grade describes your marks. A percentile describes where your score sits relative to a particular comparison group.'),('Why can the top score have a percentile below 100?','Midrank gives half-weight to tied scores, including your own. With a finite group this can place the highest score below 100.')])
add('attendance','attendance-percentage-calculator','Attendance Percentage Calculator','study','Calculate the percentage of held classes you attended.',[f('attended','Classes attended',22,0,1e6,'1'),f('classes_held','Classes held',30,1,1e6,'1')],'Attendance percentage = Classes attended ÷ Classes held × 100','Attending 22 out of 30 classes gives 22 ÷ 30 × 100 = 73.33%. Eight classes were missed. Future scheduled classes are not part of this current percentage.','Count only classes that have taken place. Attended classes cannot exceed classes held. Every class is weighted equally; canceled classes should be excluded if your institution excludes them. Excused absences, partial attendance and hour-based requirements require your institution’s own treatment.',[('Should I include classes scheduled next month?','No. Current attendance compares attended classes with classes already held.'),('Does this determine eligibility to sit an exam?','No. Your institution decides eligibility and may apply additional rules beyond a simple attendance percentage.')])
add('attendance-target','attendance-target-calculator','Attendance Target Calculator','study','Find how many consecutive future classes you need to attend to reach an attendance target.',[f('attended','Classes attended',22,0,1e6,'1'),f('classes_held','Classes held',30,1,1e6,'1'),f('target','Target attendance (%)',75,.000001)],'Additional classes = ceiling[(Target fraction × Classes held − Attended) ÷ (1 − Target fraction)]','You attended 22 of 30 classes and want 75%. Solve (22 + x) ÷ (30 + x) ≥ 0.75 to get x ≥ 2. After two consecutive attended classes, attendance is 24/32 = 75%.','Assumes every future class counts equally and you attend all of the required consecutive classes. It does not know how many classes remain in your course. If the result exceeds the actual remaining schedule, the target is not achievable that term. After an absence, exactly 100% lifetime attendance cannot be restored.',[('What if I already meet the target?','The result is zero additional classes needed to reach it now. Future absences can still lower your attendance.'),('Does this guarantee enough classes remain?','No. Compare the answer with the published course schedule.')])
add('target-gpa','target-gpa-calculator','Target GPA Calculator','gpa','Calculate the next-term GPA needed to reach a cumulative GPA target.',[scale,f('current_gpa','Current cumulative GPA',3.2,0,10),f('current_credits','Current GPA-bearing credits',45,0,1e5),f('target_gpa','Target cumulative GPA',3.3,0,10),f('next_credits','Next-term GPA-bearing credits',15,.000001,1e5)],'Required next GPA = [Target × (Current credits + Next credits) − Current GPA × Current credits] ÷ Next credits','A current 3.20 GPA across 45 credits, a 3.30 cumulative target and a 15-credit next term require (3.30 × 60 − 3.20 × 45) ÷ 15 = 3.60 next term.','Both records must use the same grade-point scale and credit system. Enter only GPA-bearing credits. The selected maximum determines whether the required next GPA is possible. Rounded current GPAs introduce estimation error, and retake replacement is not applied.',[('What if the required GPA is above my scale?','The target is not reachable in that number of credits under the selected maximum. A longer timeline or lower target may be needed.'),('Can I use this across different GPA scales?','No. Current, future and target GPA must all use the same scale.')])
add('gpa-credits','credits-to-raise-gpa-calculator','Credits to Raise GPA Calculator','gpa','Estimate the additional credits needed to reach a cumulative target at a planned future GPA.',[scale,f('current_gpa','Current cumulative GPA',3,0,10),f('current_credits','Current GPA-bearing credits',60,.000001,1e5),f('target_gpa','Target cumulative GPA',3.5,0,10),f('future_gpa','Planned GPA across new credits',4,0,10),f('credit_increment','Allowed credit increment',1,.000001,100)],'New credits = Current credits × (Target GPA − Current GPA) ÷ (Future GPA − Target GPA)','A 3.00 GPA over 60 credits needs 60 additional credits averaging 4.00 to reach 3.50: 60 × 0.50 ÷ 0.50 = 60. The result assumes the future 4.00 average is maintained across all those credits.','A higher target requires a future GPA strictly above that target to be reached in finite credits. The answer rounds upward to your allowed credit increment, not to whole courses. It does not establish that enough courses remain or that the planned future GPA is realistic.',[('Why can I not reach 4.0 from below on a 4.0 scale?','A lower existing GPA plus a finite number of 4.0 grades still averages below 4.0 if the previous grades remain counted.'),('What should I enter for credit increment?','Use the smallest credit unit you can actually add, such as 1 or 0.5. Course scheduling may impose larger practical steps.')])
add('retake-gpa','retake-gpa-calculator','Retake GPA Calculator','gpa','Compare the effect of a repeated course under replacement or both-attempts GPA rules.',[scale,f('current_gpa','Current GPA including original course',3,0,10),f('current_credits','Current GPA-bearing credits',30,.000001,1e5),f('course_credits','Repeated course credits',3,.000001,1e5),f('old_points','Original course grade points',2,0,10),f('new_points','Retake course grade points',4,0,10),sel('policy','Retake calculation policy',[['replace','Replace original attempt'],['both','Count both attempts']])],'Replacement: (Current GPA × Credits + (New − Old) × Course credits) ÷ Credits','A 3.00 GPA over 30 credits includes a 3-credit course scored at 2.00 points. Replacing it with 4.00 adds six quality points, giving 96/30 = 3.20. Counting both attempts instead gives (90 + 12) ÷ 33 = 3.09.','The current GPA must already include the original course. Both attempts must have the same credit value and scale. This tool applies your selected policy as a scenario; it does not determine your school’s actual retake eligibility, limits or transcript rules. Rounded GPA inputs can make the estimate differ slightly from official totals.',[('Which policy should I choose?','Check your registrar’s rules. Do not assume that a repeated course removes the original grade.'),('Does earned degree credit double when both attempts count?','Not necessarily. GPA-bearing attempted credits and credits earned toward graduation can be different totals.')])
add('weighted-gpa','custom-weighted-gpa-calculator','Custom Weighted GPA Calculator','gpa','Calculate a credit-weighted GPA using your own eligible course bonuses.',[text('rows','Course rows: base points, credits, bonus','4, 3, 1\n3, 3, 0.5','One course per line. Enter base grade points (0–4), credits (above 0), and your school-approved bonus (0–2), separated by commas.')],'Custom weighted GPA = Σ[(Base grade points + Bonus) × Credits] ÷ Σ(Credits)','Two 3-credit courses have base points 4.0 and 3.0, with approved bonuses of 1.0 and 0.5. Their boosted points are 5.0 and 3.5, so the equally credited weighted GPA is 4.25.','This is a configurable model, not a universal high-school weighted GPA scale. Supply only bonuses your school allows for the actual grade and course level; enter zero where no bonus applies. Base points are limited to 0–4 and a bonus to 0–2. No automatic AP, honors, failed-course or admissions recalculation rule is assumed.',[('Should every AP course receive a 1.0 bonus?','Only if your school’s policy allows that bonus for that course and grade. Policies differ.'),('Can the result exceed 4.0?','Yes. Course bonuses can produce a weighted average above the base 4.0 scale.')])
add('study-time','study-time-planner','Study Time Planner','study','Turn a topic list and review allowance into a daily study-time budget.',[f('topics','Topics to study',12,1,1e6,'1'),f('minutes_per_topic','Estimated minutes per topic',30,.000001,10000),f('days','Study days available',5,1,1e6,'1'),f('review_percent','Additional review allowance (%)',25,0,200)],'Minutes per day = Topics × Minutes per topic × (1 + Review allowance / 100) ÷ Study days','Twelve topics at 30 minutes each need 360 minutes. Adding a 25% review allowance gives 450 minutes, or 7.5 hours. Spread over five study days, that is 90 minutes each day.','The estimate spreads time evenly across available study days. It assumes each topic needs the same time and adds review as a percentage of first-pass work. This is a planning budget, not a promise of mastery. Include only days you can use, then adjust for topic difficulty, breaks and practice exams.',[('Does the review allowance include breaks?','Only if you choose to include them in that allowance. Otherwise add break time separately.'),('What if some topics take much longer?','Run separate plans for groups of similar difficulty, then combine their daily budgets.')])
add('reading-time','reading-time-calculator','Reading Time Calculator','study','Estimate reading time from page count, typical words per page and your measured speed.',[f('pages','Pages to read',20,.000001,1e6),f('words_per_page','Estimated words per page',300,.000001,10000),f('words_per_minute','Reading speed (words per minute)',200,.000001,10000)],'Reading minutes = Pages × Words per page ÷ Words per minute','Twenty pages at about 300 words each contain approximately 6,000 words. At 200 words per minute, the first-pass reading estimate is 30 minutes, or half an hour.','Words per page varies widely with formatting and subject matter. Use a sample from the actual text rather than treating the default as a measured average. This estimate excludes note-taking, problem solving, pauses and rereading. Technical material may need a different measured speed from ordinary prose.',[('How can I estimate words per page?','Count words on a few representative pages and average those counts. Avoid pages dominated by figures or blank space.'),('Is the default speed a recommendation?','No. It is an editable example value. Use a speed measured on similar material.')])
add('reading-speed','reading-speed-calculator','Reading Speed Calculator','study','Measure words per minute from a completed passage and elapsed reading time.',[f('word_count','Words actually read',600,1,1e6,'1'),f('minutes','Elapsed whole minutes',2,0,1e6,'1'),f('seconds','Additional elapsed seconds',30,0,59.999999)],'Words per minute = Words read ÷ (Minutes + Seconds / 60)','Reading 600 words in two minutes and 30 seconds takes 2.5 minutes. Your measured speed is 600 ÷ 2.5 = 240 words per minute. Count only the words you actually finished.','Use a timed passage with a known word count and enter seconds below 60. Elapsed time must be positive. The result measures pace, not comprehension or retention. For a practical study estimate, repeat on similar texts and account separately for notes and exercises.',[('Should I include time spent taking notes?','Include it only if you want to measure the combined reading-and-note-taking pace. Keep the same method when comparing sessions.'),('Does faster reading always mean better learning?','No. Understanding, recall and the task itself matter. This calculator reports pace only.')])
add('exam-time','exam-time-allocation-calculator','Exam Time Allocation Calculator','study','Budget exam minutes by mark value while reserving time for checking.',[f('exam_minutes','Total exam minutes',120,.000001,1440),f('review_minutes','Minutes reserved for checking',15,0,1440),f('total_marks','Total marks available',100,.000001,1e6),f('question_marks','Marks for this question',12,.000001,1e6)],'Question minutes = (Exam minutes − Review minutes) ÷ Total marks × Question marks','A 120-minute exam with 15 minutes reserved leaves 105 working minutes. With 100 marks available, that is 1.05 minutes per mark. A 12-mark question receives 12.6 minutes in this proportional plan.','This is a time budget based on marks, not a rule that every mark takes the same effort. Question marks cannot exceed the exam total and the checking reserve must leave positive working time. Use the marks for the questions you must answer, accounting for optional sections and the actual exam instructions.',[('Should I include marks for optional questions I will not attempt?','No. Use the total marks for the set of questions required to complete your paper.'),('What if essay and short-answer questions need different pacing?','Use this as an initial budget, then adapt it to the demands of each section and your practice-paper experience.')])
assert len(items)==23
Path(__file__).resolve().parents[1].joinpath('scripts/extra-tools.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
print('Wrote 23 original calculator specifications')
